function validate([s]) {
  if (typeof s !== 'string') return 's must be a string.';
  if (s.length > 300) return 's can have at most 300 characters.';
  const allowed = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%^&*()_+-=',.: ";
  for (const ch of s) if (!allowed.includes(ch)) return 's may only use letters, digits, spaces and !@#$%^&*()_+-=\',.:';
  return null;
}

