function countSegments(s) {
  let count = 0;

  for (let i = 0; i < s.length; i++) {
    const isStart = s[i] !== ' ' && (i === 0 || s[i - 1] === ' ');
    if (isStart) {
      count++;
    }
  }
  return count;
}

