function generate(rand, size) {
  const letters = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%^&*()_+-=',.:";
  const n = size === 'large' ? 300 : Math.floor(rand() * 13);
  const spaceChance = size === 'large' ? 0.2 + rand() * 0.3 : rand();
  let s = '';
  for (let i = 0; i < n; i++) {
    s += rand() < spaceChance ? ' ' : letters[Math.floor(rand() * letters.length)];
  }
  return [s];
}
